// Text-plane helpers (Convert nodes / Get Save Value)
static inline std::string flowNumText(float v) {
  char b[32];
  snprintf(b, sizeof(b), "%g", (double)v);
  return std::string(b);
}
static inline std::string flowPosText(float x, float y, float z) {
  char b[64];
  snprintf(b, sizeof(b), "(%g, %g, %g)", (double)x, (double)y, (double)z);
  return std::string(b);
}

// Flow variables ("Variables" nodes): shared by every graph,
// zeroed at boot, kept across scene switches, not saved to the
// memory card (use Save values for persistence).
static int flowInt[1] = {};  // mandel
class FlowGraphScript_0_0;
FlowGraphScript_0_0* g_time_FlowGraphScript_0_0 = nullptr;

// Scene "main": graph of "player-1" (object 0)
class FlowGraphScript_0_0 : public Script {
 public:
  void update(ScriptContext& ctx) override {
    if (ctx.scene != 0) return;
    // Live Debugger: nothing in this graph advances while the game is
    // stopped at a breakpoint (the loop's own pause covers the rest).
    if (livedbg::halted()) return;
    // Live Logic: while the editor has a patch for this graph, the
    // interpreter runs it instead of this compiled copy.
    if (livelogic::patched(0, 0)) return;
    if (ctx.sceneGeneration != generation) {
      // scene was (re)loaded - back to the initial state
      generation = ctx.sceneGeneration;
      frame = 0;
      started = false;
    }
    frame++;
    if (livedbg::forced(0)) {  // Live Debugger: fired from the editor
      livedbg::hit(0);
      livedbg::hit(1);
      if ((txiop::available())) {
        livedbg::hit(2);
        {
          const int iopArgs4[3] = {-32768, 0, 200};
          int iopOut4[txiop::MAX_WORDS];
          const int iopN4 = txiop::call(1, iopArgs4, 3, iopOut4, txiop::MAX_WORDS);
          if (iopN4 > 0) {
            flowInt[0] = iopOut4[0];  // "mandel"
          livedbg::hit(3);
          TYRA_LOG("IOP job 1 (Mandelbrot, 200 iters) escape count =", " ", std::to_string(flowInt[0]));
          } else {
          livedbg::hit(4);
          TYRA_LOG("IOP vanished between the check and the call - EE path");
          }
        }
      }
      else {
        livedbg::hit(5);
        TYRA_LOG("No usable IOP on this console - computing on the EE instead");
      }
    }
    if (!started) {
      started = true;
      livedbg::hit(0);
      livedbg::hit(1);
      if ((txiop::available())) {
        livedbg::hit(2);
        {
          const int iopArgs4[3] = {-32768, 0, 200};
          int iopOut4[txiop::MAX_WORDS];
          const int iopN4 = txiop::call(1, iopArgs4, 3, iopOut4, txiop::MAX_WORDS);
          if (iopN4 > 0) {
            flowInt[0] = iopOut4[0];  // "mandel"
          livedbg::hit(3);
          TYRA_LOG("IOP job 1 (Mandelbrot, 200 iters) escape count =", " ", std::to_string(flowInt[0]));
          } else {
          livedbg::hit(4);
          TYRA_LOG("IOP vanished between the check and the call - EE path");
          }
        }
      }
      else {
        livedbg::hit(5);
        TYRA_LOG("No usable IOP on this console - computing on the EE instead");
      }
    }
  }

 public:
  // Time machine (docs/time-machine.md): this graph's own
  // state - armed Delays, edge latches, latched outputs.
  FlowGraphScript_0_0() { g_time_FlowGraphScript_0_0 = this; }
  static const unsigned int kTimeBytes = 5;
  void timeCapture(unsigned char* p) const {
    memcpy(p + 0, &frame, 4);
    p[4] = started ? 1 : 0;
  }
  void timeRestore(const unsigned char* p) {
    memcpy(&frame, p + 0, 4);
    started = p[4] != 0;
  }

 private:
  unsigned int generation = 0;
  int frame = 0;
  bool started = false;
};

// Live Debugger watch table (docs/live-debugger.md): the flow variables
// in one shared order - ints, then bools, then positions.
int flowDbgVarCount() { return 1; }
void flowDbgReadVar(int index, float* out3) {
  out3[0] = out3[1] = out3[2] = 0.0F;
  switch (index) {
    case 0: out3[0] = (float)flowInt[0]; break;  // mandel
    default: break;
  }
}

// Time machine (docs/time-machine.md): every graph's own state.
